const CATEGORIES = ['Wellbeing', 'Learning', 'Fitness', 'Mindfulness', 'Creative', 'Personal'];
const todayKey = () => localDateKey(new Date());
const formatDate = date => new Intl.DateTimeFormat('en-US', { weekday: 'long', month: 'long', day: 'numeric' }).format(date);
const parseDate = key => { const [y, m, d] = key.split('-').map(Number); return new Date(y, m - 1, d); };
const dateDiff = (a, b) => Math.round((parseDate(b) - parseDate(a)) / 86400000);
function isScheduled(habit, dateKey) {
  if (dateKey < habit.startDate || (habit.endDate && dateKey > habit.endDate)) return false;
  if (habit.status !== 'active' && habit.statusChangedAt && dateKey > habit.statusChangedAt.slice(0, 10)) return false;
  const day = parseDate(dateKey).getDay();
  return habit.frequency === 'daily' || (habit.days || []).includes(day);
}
function statsForHabit(habit, completions, exclusions, today = todayKey()) {
  const completed = new Set(completions.filter(c => c.habitId === habit.id).map(c => c.date));
  const excluded = new Set(exclusions.filter(e => e.habitId === habit.id).map(e => e.date));
  const start = habit.startDate > today ? today : habit.startDate;
  const total = Math.max(0, dateDiff(start, today));
  let scheduled = 0, done = 0, streak = 0, best = 0, running = 0;
  const history = [];
  for (let i = 0; i <= total; i++) {
    const key = localDateKey(new Date(parseDate(start).getFullYear(), parseDate(start).getMonth(), parseDate(start).getDate() + i));
    if (!isScheduled(habit, key)) continue;
    if (excluded.has(key)) { history.push({ date: key, state: 'excluded' }); running = 0; continue; }
    scheduled++;
    if (completed.has(key)) { done++; running++; best = Math.max(best, running); history.push({ date: key, state: 'done' }); }
    else { history.push({ date: key, state: key === today ? 'pending' : 'missed' }); running = 0; }
  }
  for (let i = history.length - 1; i >= 0; i--) {
    const day = history[i];
    if (day.date === today && day.state === 'pending') continue;
    if (day.state === 'done') streak++; else if (day.state !== 'excluded') break;
  }
  return { scheduled, done, rate: scheduled ? Math.round(done / scheduled * 100) : 0, streak, best, history };
}
