function TaskForm({ task, initialDate, defaultReminder = 0, onClose, onSave }) {
  const [title, setTitle] = useState(task?.title || '');
  const [notes, setNotes] = useState(task?.notes || '');
  const [dueDate, setDueDate] = useState(task?.dueDate || initialDate || todayKey());
  const [startTime, setStartTime] = useState(task?.startTime || '');
  const [deadline, setDeadline] = useState(task?.deadline || '');
  const [priority, setPriority] = useState(task?.priority || 'medium');
  const [category, setCategory] = useState(task?.category || 'Personal');
  const [reminderMinutes, setReminderMinutes] = useState(String(task ? (task.reminderMinutes ?? 0) : defaultReminder));
  const [voiceMessage, setVoiceMessage] = useState('');
  const [error, setError] = useState('');
  const [listening, setListening] = useState(false);
  const recognize = () => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) { setVoiceMessage('Voice entry is not supported in this browser. Please type your task instead.'); return; }
    try {
      const recognition = new SpeechRecognition(); recognition.lang = 'en-US'; recognition.interimResults = false; recognition.maxAlternatives = 1;
      recognition.onstart = () => { setListening(true); setVoiceMessage('Listening… say your task, date and time.'); };
      recognition.onerror = e => { setListening(false); setVoiceMessage(e.error === 'not-allowed' ? 'Microphone permission was denied. You can still type your task.' : 'Could not recognize speech. Please try again or type your task.'); };
      recognition.onend = () => setListening(false);
      recognition.onresult = e => {
        let spoken = e.results[0][0].transcript.trim(); let parsedTitle = spoken;
        const lower = spoken.toLowerCase(); const now = new Date();

        // Extract reminder intent before setting the task title.
        const reminderMatch = lower.match(/\b(?:(?:remind me\s+)?(\d+)\s+minutes?\s+(?:before(?:\s+the\s+task)?|early)|remind me\s+at\s+the\s+time)\b/i);
        if (reminderMatch) {
          if (reminderMatch[1]) setReminderMinutes(reminderMatch[1]);
          else setReminderMinutes('0');
          parsedTitle = parsedTitle.replace(new RegExp(reminderMatch[0].replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i'), '');
        }

        if (/\btomorrow\b/i.test(lower)) { const d = new Date(now.getFullYear(), now.getMonth(), now.getDate()+1); setDueDate(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`); parsedTitle = parsedTitle.replace(/\btomorrow\b/i,''); }
        else if (/\btoday\b/i.test(lower)) { setDueDate(todayKey()); parsedTitle = parsedTitle.replace(/\btoday\b/i,''); }
        const timeMatch = lower.match(/\b(\d{1,2})(?::(\d{2}))?\s*(a\.?m\.?|p\.?m\.?)\b/i);
        if (timeMatch) { let hour=Number(timeMatch[1])%12; if (/p/i.test(timeMatch[3])) hour+=12; setStartTime(`${String(hour).padStart(2,'0')}:${timeMatch[2]||'00'}`); parsedTitle=parsedTitle.replace(/\s+\bat\s+(?=\d{1,2}(?::\d{2})?\s*(?:a\.?m\.?|p\.?m\.?))/i,' '); parsedTitle=parsedTitle.replace(/\b\d{1,2}(?::\d{2})?\s*(?:a\.?m\.?|p\.?m\.?)/i,''); }
        parsedTitle = parsedTitle.replace(/^\s*(remind me to|please|add a task to|add task to)\s*/i,'').replace(/\band\s*$/i,'').replace(/\s+at\s*[,.]?\s*$/i,'').replace(/[,.!?]+$/,'').trim();
        setTitle(parsedTitle || spoken); setVoiceMessage(`Heard: “${spoken}”. ${reminderMatch ? `Reminder set to ${reminderMatch[1] || 'no'} minutes before the task. ` : ''}Review the title, date, time and reminder below before saving.`);
      };
      recognition.start();
    } catch { setListening(false); setVoiceMessage('Voice entry could not start. Please type your task instead.'); }
  };
  const enableReminder = async value => {
    setReminderMinutes(value);
    if (Number(value) > 0 && 'Notification' in window && Notification.permission === 'default') {
      try { const permission = await Notification.requestPermission(); if (permission !== 'granted') setVoiceMessage('Notifications were not enabled. In-app reminders work only while Daymark is open.'); }
      catch { setVoiceMessage('Notifications are unavailable here. In-app reminders work only while Daymark is open.'); }
    } else if (Number(value)>0 && (!('Notification' in window) || Notification.permission !== 'granted')) setVoiceMessage('Browser notifications are unavailable or blocked. In-app reminders work only while Daymark is open.');
  };
  const submit = async e => { e.preventDefault(); if (!title.trim()) { setError('Add a task title.'); return; } if (startTime && deadline && deadline < startTime) { setError('Deadline must be after the start time.'); return; }
    await onSave({ ...(task || {}), id: task?.id || makeId(), title: title.trim(), notes: notes.trim(), dueDate: dueDate || '', startTime, deadline, priority, category, reminderMinutes: Number(reminderMinutes), reminderSentFor: task?.reminderSentFor || '', completed: task?.completed || false, completedAt: task?.completedAt || null, createdAt: task?.createdAt || new Date().toISOString() }); };
  return <div className="modal-scrim" role="presentation" onMouseDown={e => e.target === e.currentTarget && onClose()}><section className="entry-modal task-form-modal" role="dialog" aria-modal="true" aria-labelledby="task-entry-title"><div className="modal-heading"><div><span className="tiny-label">MAKE ROOM FOR WHAT MATTERS</span><h2 id="task-entry-title">{task ? 'Edit task' : 'Add a task'}</h2></div><button className="icon-button" onClick={onClose} aria-label="Close"><X size={19}/></button></div><form onSubmit={submit}><div className="voice-entry-row"><button type="button" className="secondary-button" onClick={recognize} disabled={listening}><Mic size={16}/>{listening ? 'Listening…' : 'Speak task'}</button><span className="voice-hint">Try: “Practise DSA tomorrow at four PM”</span></div>{voiceMessage && <p className="form-hint" role="status">{voiceMessage}</p>}<label className="field-label" htmlFor="task-title">Task title *</label><input id="task-title" className="text-input" value={title} onChange={e => setTitle(e.target.value)} placeholder="e.g. Practise DSA for 45 minutes" maxLength={140} autoFocus required/><label className="field-label" htmlFor="task-notes">Notes <span className="optional-label">OPTIONAL</span></label><textarea id="task-notes" className="text-input habit-textarea" rows={2} value={notes} onChange={e => setNotes(e.target.value)} placeholder="Details, links, or a reminder to yourself" maxLength={1200}/><div className="form-two-col"><div><label className="field-label" htmlFor="task-date">Due date <span className="optional-label">OPTIONAL · BLANK = BACKLOG</span></label><input id="task-date" type="date" className="text-input" value={dueDate} onChange={e => setDueDate(e.target.value)}/></div><div><label className="field-label" htmlFor="task-category">Category</label><select id="task-category" className="text-input" value={category} onChange={e => setCategory(e.target.value)}>{['Personal','Learning','College','Work','Fitness','Creative'].map(c => <option key={c}>{c}</option>)}</select></div></div><div className="form-three-col"><div><label className="field-label" htmlFor="task-start">Start time</label><input id="task-start" type="time" className="text-input" value={startTime} onChange={e => setStartTime(e.target.value)}/></div><div><label className="field-label" htmlFor="task-deadline">Deadline</label><input id="task-deadline" type="time" className="text-input" value={deadline} onChange={e => setDeadline(e.target.value)}/></div><div><label className="field-label" htmlFor="task-priority">Priority</label><select id="task-priority" className="text-input" value={priority} onChange={e => setPriority(e.target.value)}><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select></div></div><label className="field-label" htmlFor="task-reminder"><Bell size={14}/> Reminder</label><select id="task-reminder" className="text-input" value={reminderMinutes} onChange={e=>enableReminder(e.target.value)}><option value="0">No reminder</option><option value="5">5 minutes before</option><option value="10">10 minutes before</option><option value="15">15 minutes before</option><option value="30">30 minutes before</option></select><p className="form-hint">Reminders use the task start time and run while Daymark is open. Browser notifications depend on permission and device support; they are not guaranteed when the browser is closed.</p>{error && <p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Cancel</button><button type="submit" className="primary-button"><Check size={16}/>{task ? 'Save changes' : 'Add task'}</button></div></form></section></div>;
}
function TaskCard({ task, onToggle, onEdit, onDelete, onReschedule }) {
  const today = todayKey(); const overdue = !task.completed && task.dueDate && task.dueDate < today;
  const dateLabel = task.dueDate ? new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: task.dueDate.slice(0,4) !== today.slice(0,4) ? 'numeric' : undefined }).format(parseDate(task.dueDate)) : 'Backlog';
  return <article className={`task-item ${task.completed ? 'is-completed' : ''} ${overdue ? 'is-overdue' : ''}`}><button className={`task-check ${task.completed ? 'checked' : ''}`} onClick={() => onToggle(task)} aria-label={task.completed ? `Mark ${task.title} incomplete` : `Complete ${task.title}`}>{task.completed && <Check size={15}/>}</button><div className="task-item-main"><div className="task-title-row"><h3>{task.title}</h3><span className={`priority-pill priority-${task.priority}`}>{task.priority}</span></div>{task.notes && <p className="task-notes">{task.notes}</p>}<div className="task-meta"><span><CalendarDays size={13}/>{dateLabel}</span>{task.startTime && <span><Clock3 size={13}/>{task.startTime}{task.deadline ? `–${task.deadline}` : ''}</span>}<span>{task.category}</span>{overdue && <strong className="overdue-label">Overdue</strong>}</div></div><div className="task-actions"><button className="subtle-icon" onClick={() => onEdit(task)} aria-label={`Edit ${task.title}`} title="Edit"><Pencil size={15}/></button><button className="subtle-icon" onClick={() => onReschedule(task)} aria-label={`Reschedule ${task.title}`} title="Reschedule"><CalendarDays size={15}/></button><button className="subtle-icon danger-icon" onClick={() => onDelete(task)} aria-label={`Delete ${task.title}`} title="Delete"><Trash2 size={15}/></button></div></article>;
}
function EmptyTasks({ filter, onAdd }) { const copy = { today: ['Nothing on your list yet','Add a task you want to make time for today.'], upcoming: ['A little space ahead','Tasks scheduled for future dates will show up here.'], overdue: ['You’re all caught up','No unfinished tasks are past their due date.'], completed: ['Every finish starts somewhere','Completed tasks will collect here.'], backlog: ['A clear mind starts here','Capture tasks without choosing a date yet.'] }[filter]; return <section className="empty-state simple-empty"><div className="round-illustration mint"><ListTodo size={30}/></div><span className="tiny-label">ONE THING AT A TIME</span><h2>{copy[0]}</h2><p>{copy[1]}</p><button className="primary-button" onClick={onAdd}><Plus size={17}/> Add a task</button></section>; }

function TaskProgress({ tasks }) {
  const [dailyStart, setDailyStart] = useState(todayKey()); const [dailyEnd, setDailyEnd] = useState(todayKey());
  const [trendStart, setTrendStart] = useState(dateOffset(6)); const [trendEnd, setTrendEnd] = useState(todayKey());
  const [heatStart, setHeatStart] = useState(`${new Date().getFullYear()}-01-01`); const [heatEnd, setHeatEnd] = useState(todayKey());
  const makeDay = date => { const due=tasks.filter(t=>t.dueDate===date); const done=due.filter(t=>t.completed).length; return {date,due:due.length,done,rate:due.length?Math.round(done/due.length*100):null}; };
  const dailyRateDays=rangeDates(dailyStart,dailyEnd).map(makeDay), trendDays=rangeDates(trendStart,trendEnd).map(makeDay), heatmapDays=rangeDates(heatStart,heatEnd).map(makeDay);
  const overdue=tasks.filter(t=>!t.completed&&t.dueDate&&t.dueDate<todayKey()).length;
  const periodTasks=tasks.filter(t=>t.dueDate&&t.dueDate>=trendStart&&t.dueDate<=trendEnd);
  const completed=periodTasks.filter(t=>t.completed).length;
  return <><div className="habit-analytics-grid"><div className="analytics-stat panel"><span className="analytics-label">TASKS IN TREND RANGE</span><div className="analytics-number">{periodTasks.length}</div><p>{completed} completed tasks due in the selected trend range</p><div className="habit-progress-track"><span style={{width:`${periodTasks.length?Math.round(completed/periodTasks.length*100):0}%`}}/></div></div><div className="analytics-stat panel"><span className="analytics-label">OVERDUE NOW</span><div className="analytics-number">{overdue}</div><p>Unfinished tasks with a due date before today</p><div className="analytics-stat-foot"><ListTodo size={15}/> Tasks stay incomplete until completed</div></div></div><AnalyticsCharts dailyRateDays={dailyRateDays} trendDays={trendDays} heatmapDays={heatmapDays} kind="Tasks" dailyStart={dailyStart} dailyEnd={dailyEnd} setDailyStart={setDailyStart} setDailyEnd={setDailyEnd} trendStart={trendStart} trendEnd={trendEnd} setTrendStart={setTrendStart} setTrendEnd={setTrendEnd} heatStart={heatStart} heatEnd={heatEnd} setHeatStart={setHeatStart} setHeatEnd={setHeatEnd}/><div className="task-metric-row"><div className="panel task-metric"><span>Tasks due in trend range</span><strong>{periodTasks.length}</strong></div><div className="panel task-metric"><span>Completed</span><strong>{completed}</strong></div><div className="panel task-metric"><span>Rescheduled records*</span><strong>{periodTasks.filter(t=>(t.rescheduleCount||0)>0).length}</strong></div></div><p className="analytics-footnote">*Rescheduling history is shown only when a task record contains a reschedule count.</p></>;
}

function CalendarPage({ tasks, habits, completions, exclusions, onAddTask, onAddHabit, onToggleTask }) {
  const [month, setMonth] = useState(() => { const d = new Date(); return new Date(d.getFullYear(), d.getMonth(), 1); });
  const [selected, setSelected] = useState(todayKey());
  const monthStart = new Date(month.getFullYear(), month.getMonth(), 1);
  const offset = (monthStart.getDay() + 6) % 7;
  const cells = Array.from({length:42}, (_, i) => { const d = new Date(month.getFullYear(), month.getMonth(), i - offset + 1); return { date: localDateKey(d), day: d.getDate(), inMonth: d.getMonth() === month.getMonth() }; });
  const selectedTasks = tasks.filter(t => t.dueDate === selected);
  const selectedHabits = habits.filter(h => h.status === 'active' && isScheduled(h, selected));
  const completedIds = new Set(completions.filter(c => c.date === selected).map(c => c.habitId));
  const excludedIds = new Set(exclusions.filter(x => x.date === selected).map(x => x.habitId));
  const monthLabel = new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric'}).format(month);
  return <div className="calendar-layout"><section className="panel calendar-panel"><div className="calendar-toolbar"><div><h2>{monthLabel}</h2><p>Choose a date to plan ahead</p></div><div className="calendar-controls"><button className="secondary-button compact-button" onClick={()=>{const d=new Date();setMonth(new Date(d.getFullYear(),d.getMonth(),1));setSelected(todayKey());}}>Today</button><button className="icon-button" aria-label="Previous month" onClick={()=>setMonth(m=>new Date(m.getFullYear(),m.getMonth()-1,1))}><ChevronDown className="rotate-left" size={18}/></button><button className="icon-button" aria-label="Next month" onClick={()=>setMonth(m=>new Date(m.getFullYear(),m.getMonth()+1,1))}><ChevronDown className="rotate-right" size={18}/></button></div></div><div className="calendar-grid calendar-weekdays">{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((d,i)=><div key={`${d}-${i}`}>{d}</div>)}</div><div className="calendar-grid">{cells.map(cell=>{const dayTasks=tasks.filter(t=>t.dueDate===cell.date);const dayHabits=habits.filter(h=>h.status==='active'&&isScheduled(h,cell.date));return <button key={cell.date} className={`calendar-day ${cell.inMonth?'':'outside-month'} ${selected===cell.date?'selected':''} ${cell.date===todayKey()?'is-today':''}`} onClick={()=>setSelected(cell.date)} aria-pressed={selected===cell.date}><span>{cell.day}</span><span className="calendar-dots" aria-label={`${dayTasks.length} tasks, ${dayHabits.length} scheduled habits`}>{dayTasks.length>0&&<i className="task-dot"/>}{dayHabits.length>0&&<i className="habit-dot"/>}</span></button>})}</div><div className="calendar-legend"><span><i className="task-dot"/> Tasks due</span><span><i className="habit-dot"/> Scheduled habits</span></div></section><aside className="panel calendar-day-panel"><div className="calendar-selected-date"><span className="tiny-label">SELECTED DAY</span><h2>{new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric'}).format(parseDate(selected))}</h2><p>{selected===todayKey()?'Today':selected<todayKey()?'Past date':'Plan ahead'}</p></div><div className="calendar-section-heading"><h3>Scheduled habits</h3><span>{selectedHabits.length}</span></div>{selectedHabits.length?selectedHabits.map(h=><div className="calendar-item" key={h.id}><span className="calendar-item-marker habit-dot"/><div><strong>{h.name}</strong><small>{excludedIds.has(h.id)?'Rest day':completedIds.has(h.id)?'Completed':'Scheduled habit'}</small></div></div>):<p className="calendar-empty-copy">No active habits scheduled for this date.</p>}<div className="calendar-section-heading task-section-heading"><h3>Tasks</h3><span>{selectedTasks.length}</span></div>{selectedTasks.length?selectedTasks.map(t=><div className={`calendar-item ${t.completed?'calendar-item-completed':''}`} key={t.id}><button className={`task-check ${t.completed?'checked':''}`} onClick={()=>onToggleTask(t)} aria-label={t.completed?'Reopen task':'Complete task'}>{t.completed&&<Check size={13}/>}</button><div><strong>{t.title}</strong><small>{t.startTime?`${t.startTime}${t.deadline?`–${t.deadline}`:''} · `:''}{t.priority} priority{t.completed?' · completed':''}</small></div></div>):<p className="calendar-empty-copy">No tasks due on this date.</p>}<div className="calendar-actions"><button className="primary-button full-button" onClick={()=>onAddTask(selected)}><Plus size={16}/> Add task on this date</button><button className="secondary-button full-button" onClick={onAddHabit}><Plus size={16}/> Add habit</button></div></aside></div>;
}

function App() {
  const [page, setPage] = useState('tasks');
  const [theme, setTheme] = useState(() => { try { return localStorage.getItem('daymark-theme') || 'light'; } catch { return 'light'; } });
  const [menuOpen, setMenuOpen] = useState(false); const [entryKind, setEntryKind] = useState(null); const [editingHabit, setEditingHabit] = useState(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showBulkTasks, setShowBulkTasks] = useState(false); const [showBulkHabits, setShowBulkHabits] = useState(false);
  const [defaultReminder, setDefaultReminder] = useState(() => { try { return Number(localStorage.getItem('daymark-default-reminder') || 0); } catch { return 0; } });
  const [profileName, setProfileName] = useState(() => { try { return localStorage.getItem('daymark-profile-name') || ''; } catch { return ''; } });
  const [calendarTaskDate, setCalendarTaskDate] = useState(''); const [showHelp, setShowHelp] = useState(false); const [backupBusy, setBackupBusy] = useState(false); const [tasks, setTasks] = useState([]); const [taskFilter, setTaskFilter] = useState('today'); const [editingTask, setEditingTask] = useState(null); const [reschedulingTask, setReschedulingTask] = useState(null); const [habits, setHabits] = useState([]); const [completions, setCompletions] = useState([]); const [exclusions, setExclusions] = useState([]); const [loading, setLoading] = useState(true); const [dbError, setDbError] = useState(''); const [toast, setToast] = useState(''); const [habitFilter, setHabitFilter] = useState('active');
  const refresh = useCallback(async () => { try { const [h, c, x, t] = await Promise.all([getHabits(), getCompletions(), getExclusions(), getTasks()]); setTasks(t.sort((a, b) => (a.dueDate || '9999-12-31').localeCompare(b.dueDate || '9999-12-31') || a.createdAt.localeCompare(b.createdAt))); setHabits(h.sort((a, b) => a.createdAt.localeCompare(b.createdAt))); setCompletions(c); setExclusions(x); setDbError(''); } catch (e) { setDbError(`${e.message} Try opening this app in a current version of Chrome or Edge.`); } finally { setLoading(false); } }, []);
  useEffect(() => {
    const checkReminders = () => {
      const now = new Date(); const today = todayKey();
      tasks.forEach(task => {
        if (!task || task.completed || !task.dueDate || !task.startTime || !Number(task.reminderMinutes) || task.dueDate !== today) return;
        const [h,m] = task.startTime.split(':').map(Number); const due = new Date(now.getFullYear(), now.getMonth(), now.getDate(), h, m); const remindAt = due.getTime() - Number(task.reminderMinutes)*60000;
        const marker = `${task.dueDate}T${task.startTime}:${task.reminderMinutes}`;
        if (now.getTime() >= remindAt && now.getTime() <= due.getTime() && task.reminderSentFor !== marker) {
          const updated = { ...task, reminderSentFor: marker }; saveTask(updated).then(refresh).catch(()=>{});
          setToast(`Reminder: ${task.title}`);
          if ('Notification' in window && Notification.permission === 'granted') { try { new Notification('Daymark reminder', { body: task.title }); } catch {} }
        }
      });
    };
    checkReminders(); const timer = window.setInterval(checkReminders, 30000); return () => window.clearInterval(timer);
  }, [tasks, refresh]);

  useEffect(() => { refresh(); }, [refresh]);
  useEffect(() => { document.documentElement.dataset.theme = theme; try { localStorage.setItem('daymark-theme', theme); } catch {} }, [theme]);
  const notify = message => { setToast(message); window.setTimeout(() => setToast(''), 2600); };
  const exportBackup = async () => {
    setBackupBusy(true);
    try {
      const backup = await createBackup();
      const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob); const link = document.createElement('a');
      link.href = url; link.download = `daymark-backup-${localDateKey(new Date())}.json`;
      document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url);
      notify('Backup downloaded');
    } catch (error) { notify(error.message || 'Could not create backup'); }
    finally { setBackupBusy(false); }
  };
  const importBackup = async event => {
    const file = event.target.files?.[0]; event.target.value = '';
    if (!file) return;
    if (!window.confirm('Restoring a backup replaces all Daymark tasks, habits, and history on this device. Export a backup of your current data first if you want to keep it. Continue?')) return;
    setBackupBusy(true);
    try {
      const parsed = JSON.parse(await file.text());
      await restoreBackup(parsed); await refresh(); setShowHelp(false); notify('Backup restored successfully');
    } catch (error) { window.alert(error.message || 'Could not restore this backup.'); }
    finally { setBackupBusy(false); }
  };
  const closeMenu = () => setMenuOpen(false);
  const chooseAdd = kind => { setMenuOpen(false); if (kind === 'habit') { setEditingHabit(null); setShowBulkHabits(true); } else { setEditingTask(null); setShowBulkTasks(true); } };
  const saveHabitHandler = async habit => { try { await saveHabit(habit); await refresh(); setEntryKind(null); setEditingHabit(null); notify(habit.updatedAt && habits.some(h => h.id === habit.id) ? 'Habit updated' : 'Habit created'); } catch (e) { setDbError(`Could not save this habit: ${e.message}`); } };
  const toggleCompletion = async habit => { const date = todayKey(); const exists = completions.some(c => c.habitId === habit.id && c.date === date); try { await setHabitCompletion(habit.id, date, !exists); await refresh(); notify(exists ? 'Completion undone' : 'Habit completed — nice work'); } catch (e) { setDbError(`Could not update completion: ${e.message}`); } };
  const toggleExclusion = async habit => { const date = todayKey(); const exists = exclusions.some(x => x.habitId === habit.id && x.date === date); try { await setExclusion(habit.id, date, !exists); await refresh(); notify(exists ? 'Today restored to your schedule' : 'Today marked as a rest day'); } catch (e) { setDbError(`Could not update rest day: ${e.message}`); } };
  const updateStatus = async (habit, status) => { try { await saveHabit({ ...habit, status, statusChangedAt: new Date().toISOString(), updatedAt: new Date().toISOString() }); await refresh(); notify(status === 'active' ? 'Habit resumed' : `Habit ${status}`); } catch (e) { setDbError(e.message); } };
  const deleteHabitHandler = async habit => { if (!window.confirm(`Delete “${habit.name}” and its completion history? This cannot be undone.`)) return; try { await removeHabit(habit.id); await refresh(); notify('Habit and its history deleted'); } catch (e) { setDbError(`Could not delete habit: ${e.message}`); } };
  const saveTaskHandler = async task => { try { await saveTask(task); await refresh(); setEntryKind(null); setEditingTask(null); setCalendarTaskDate(''); notify(task.updatedAt ? 'Task updated' : 'Task created'); } catch (e) { setDbError(`Could not save task: ${e.message}`); } };
  const saveManyTasksHandler = async newTasks => { try { for (const task of newTasks) await saveTask(task); await refresh(); setShowBulkTasks(false); notify(`${newTasks.length} tasks added`); } catch (e) { setDbError(`Could not add all tasks: ${e.message}`); } };
  const saveManyHabitsHandler = async newHabits => { try { for (const habit of newHabits) await saveHabit(habit); await refresh(); setShowBulkHabits(false); notify(`${newHabits.length} habits added`); } catch (e) { setDbError(`Could not add all habits: ${e.message}`); } };
  const saveDefaultReminder = value => { setDefaultReminder(value); try { localStorage.setItem('daymark-default-reminder', String(value)); } catch {} setShowSettings(false); notify('Default reminder saved'); };
  const saveProfileName = value => { const clean = value.trim().slice(0, 60); setProfileName(clean); try { localStorage.setItem('daymark-profile-name', clean); } catch {} notify('Profile updated'); };
  const toggleTask = async task => { try { await saveTask({ ...task, completed: !task.completed, completedAt: task.completed ? null : new Date().toISOString() }); await refresh(); notify(task.completed ? 'Task marked incomplete' : 'Task completed'); } catch (e) { setDbError(`Could not update task: ${e.message}`); } };
  const deleteTaskHandler = async task => { if (!window.confirm(`Delete “${task.title}”? This cannot be undone.`)) return; try { await deleteTask(task.id); await refresh(); notify('Task deleted'); } catch (e) { setDbError(`Could not delete task: ${e.message}`); } };
  const rescheduleTaskHandler = async task => { const nextDate = window.prompt('Enter a new due date (YYYY-MM-DD), or leave blank to move to Backlog:', task.dueDate || ''); if (nextDate === null) return; if (nextDate && !/^\d{4}-\d{2}-\d{2}$/.test(nextDate)) { setDbError('Use the date format YYYY-MM-DD.'); return; } try { await saveTask({ ...task, dueDate: nextDate }); await refresh(); notify(nextDate ? 'Task rescheduled' : 'Task moved to backlog'); } catch (e) { setDbError(`Could not reschedule task: ${e.message}`); } };
  const visibleTasks = useMemo(() => { const today = todayKey(); return tasks.filter(t => { if (taskFilter === 'completed') return t.completed; if (t.completed) return false; if (taskFilter === 'today') return t.dueDate === today; if (taskFilter === 'upcoming') return t.dueDate > today; if (taskFilter === 'overdue') return t.dueDate && t.dueDate < today; if (taskFilter === 'backlog') return !t.dueDate; return false; }); }, [tasks, taskFilter]);
  const pageCopy = PAGE_COPY[page];
  const activeHabits = useMemo(() => habits.filter(h => habitFilter === 'all' || h.status === habitFilter), [habits, habitFilter]);
  const todayDone = completions.filter(c => c.date === todayKey()).length;
  return <div className="app-shell" data-theme={theme}>
    <aside className="desktop-rail" aria-label="Main navigation"><button className="brand-lockup" onClick={() => setPage('tasks')} aria-label="Daymark home"><span className="brand-mark"><Waves size={22} /></span><span className="brand-name">daymark<span>.</span><small>YOUR SPACE TO GROW</small></span></button><div className="rail-label">WORKSPACE</div><nav className="rail-nav">{NAV_ITEMS.slice(0, 2).map(item => <NavButton key={item.id} item={item} active={page === item.id} onClick={() => setPage(item.id)} />)}<div className="rail-separator" />{NAV_ITEMS.slice(2).map(item => <NavButton key={item.id} item={item} active={page === item.id} onClick={() => setPage(item.id)} />)}</nav><div className="rail-bottom-card"><div className="rail-card-icon"><Sparkles size={18} /></div><strong>Small steps add up.</strong><p>You don't have to do it all. Just begin with one thing.</p></div><div className="rail-footer"><span className="avatar">{(profileName.trim()[0] || 'D').toUpperCase()}</span><span className="footer-profile"><strong>{profileName.trim() || 'Your space'}</strong><small>Stored on this device</small></span><button className="subtle-icon" aria-label="Workspace help" onClick={() => setShowHelp(true)}><Settings2 size={17} /></button></div></aside>
    <main className="main-area"><header className="topbar"><div className="mobile-brand"><span className="brand-mark"><Waves size={19} /></span><span>daymark<span>.</span></span></div><div className="breadcrumb"><span>Workspace</span><span className="crumb-slash">/</span><strong>{pageCopy.title}</strong></div><div className="topbar-actions"><button className={`secondary-button calendar-open-button ${page === 'calendar' ? 'selected' : ''}`} onClick={() => setPage(page === 'calendar' ? 'tasks' : 'calendar')}><CalendarDays size={15}/> Calendar</button><div className="today-chip"><CalendarDays size={15} /><span>{formatDate(new Date())}</span></div><ThemeToggle theme={theme} onToggle={() => setTheme(theme === 'light' ? 'dark' : 'light')} /><button className="help-button" onClick={() => setShowSettings(true)} aria-label="Settings" title="Settings"><Settings2 size={18} /></button><button className="help-button" onClick={() => setShowHelp(true)} aria-label="Help"><CircleHelp size={18} /></button></div></header>
    <div className="page-content"><div className="page-heading-row"><div><div className="eyebrow"><span className="eyebrow-dot" />{pageCopy.eyebrow}</div><h1>{pageCopy.title}<span className="heading-period">.</span></h1><p className="page-subtitle">{pageCopy.subtitle}</p></div><div className="heading-actions"><span className="date-filter"><CalendarDays size={15}/><span>{page.includes('progress') ? 'Recent activity' : 'Today'}</span></span>{(page === 'habits' || page === 'habit-progress') && <button className="primary-button desktop-add" onClick={() => { setEditingHabit(null); setShowBulkHabits(true); }}><Plus size={17}/> Add to list</button>}</div></div>
    {dbError && <div className="database-error" role="alert"><AlertCircle size={17}/><span>{dbError}</span><button className="subtle-icon" onClick={() => setDbError('')} aria-label="Dismiss error"><X size={16}/></button></div>}
    {page === 'tasks' && <><div className="daily-banner"><div className="banner-icon"><Sun size={22}/></div><div className="banner-copy"><strong>A new day, a new chance.</strong><span>Plan a little, then focus on the next thing.</span></div><div className="banner-decoration"><span/><span/><span/></div><div className="banner-date">{new Intl.DateTimeFormat('en-US', { month: 'short', day: '2-digit' }).format(new Date()).toUpperCase()}</div></div><div className="task-overview-grid"><div className="overview-card focus-card"><div className="overview-top"><span className="overview-icon orange"><Zap size={17}/></span><span className="overview-caption">TODAY'S TASKS</span></div><div className="overview-value">{tasks.filter(t => t.dueDate === todayKey() && !t.completed).length} <small>to do</small></div><div className="overview-bottom"><span>{tasks.filter(t => t.dueDate === todayKey() && t.completed).length} completed today</span></div></div><div className="overview-card rhythm-card"><div className="overview-top"><span className="overview-icon green"><CheckCheck size={17}/></span><span className="overview-caption">HABITS COMPLETED TODAY</span></div><div className="overview-value">{todayDone} <small>completed</small></div><div className="overview-bottom"><span>Habits are tracked separately</span></div></div></div><section className="tasks-panel"><div className="tasks-panel-heading"><div><h2>Your task list</h2><p>{visibleTasks.length} {visibleTasks.length === 1 ? 'task' : 'tasks'} · unfinished tasks stay unfinished until you complete them</p></div><div className="task-heading-actions"><button className="secondary-button" onClick={() => setShowBulkTasks(true)}><ListTodo size={16}/> Add to list</button><button className="primary-button" onClick={() => { setEditingTask(null); setShowBulkTasks(true); }}><Plus size={17}/> Add task</button></div></div><div className="task-filter-tabs" role="group" aria-label="Filter tasks">{[['today','Today'],['upcoming','Upcoming'],['overdue','Overdue'],['completed','Completed'],['backlog','Backlog']].map(([id,label]) => <button key={id} className={taskFilter === id ? 'selected' : ''} onClick={() => setTaskFilter(id)}>{label}{id === 'overdue' && tasks.filter(t => !t.completed && t.dueDate && t.dueDate < todayKey()).length > 0 && <span className="filter-count">{tasks.filter(t => !t.completed && t.dueDate && t.dueDate < todayKey()).length}</span>}</button>)}</div>{loading ? <div className="loading-state">Loading your tasks…</div> : visibleTasks.length ? <div className="task-list">{visibleTasks.map(task => <TaskCard key={task.id} task={task} onToggle={toggleTask} onEdit={t => { setEditingTask(t); setEntryKind('task'); }} onDelete={deleteTaskHandler} onReschedule={rescheduleTaskHandler}/>)}</div> : <EmptyTasks filter={taskFilter} onAdd={() => { setEditingTask(null); setEntryKind('task'); }}/>}</section></>}
    {page === 'habits' && <><div className="section-heading standalone-section"><div><h2>Routines worth keeping</h2><p>{habits.filter(h => h.status === 'active').length} active · saved privately on this device</p></div><div className="habit-filter-tabs" role="group" aria-label="Filter habits">{[['active','Active'],['paused','Paused'],['archived','Archived'],['all','All']].map(([id,label]) => <button key={id} className={habitFilter === id ? 'selected' : ''} onClick={() => setHabitFilter(id)}>{label}</button>)}</div></div>{loading ? <div className="loading-state">Loading your habits…</div> : activeHabits.length === 0 ? <EmptyHabits onAdd={() => { setEditingHabit(null); setShowBulkHabits(true); }} /> : <div className="habit-list">{activeHabits.map(habit => <HabitCard key={habit.id} habit={habit} stats={statsForHabit(habit, completions, exclusions)} completedToday={completions.some(c => c.habitId === habit.id && c.date === todayKey())} excludedToday={exclusions.some(x => x.habitId === habit.id && x.date === todayKey())} onToggle={toggleCompletion} onEdit={h => { setEditingHabit(h); setEntryKind('habit'); }} onStatus={updateStatus} onDelete={deleteHabitHandler} onExclude={toggleExclusion}/>)}</div>}</>}
    {page === 'habit-progress' && (loading ? <div className="loading-state">Loading your habit history…</div> : <ProgressHabits habits={habits} completions={completions} exclusions={exclusions} onAdd={() => { setEditingHabit(null); setEntryKind('habit'); }}/>) }
    {page === 'task-progress' && (loading ? <div className="loading-state">Loading task history…</div> : <TaskProgress tasks={tasks}/>)}
    {page === 'calendar' && <CalendarPage tasks={tasks} habits={habits} completions={completions} exclusions={exclusions} onAddTask={date => { setCalendarTaskDate(date); setEditingTask(null); setEntryKind('task'); }} onAddHabit={() => { setEditingHabit(null); setEntryKind('habit'); }} onToggleTask={toggleTask}/>}
    <footer className="page-footer"><span>Made for progress, not perfection.</span><span className="footer-leaf"><Leaf size={13}/> Stored locally on this device</span></footer></div></main>
    <nav className="bottom-nav" aria-label="Bottom navigation"><NavButton item={NAV_ITEMS[0]} active={page === NAV_ITEMS[0].id} onClick={() => setPage(NAV_ITEMS[0].id)} compact/><NavButton item={NAV_ITEMS[1]} active={page === NAV_ITEMS[1].id} onClick={() => setPage(NAV_ITEMS[1].id)} compact/><div className="add-nav-slot"><button className={`central-add ${menuOpen ? 'is-open' : ''}`} onClick={() => setMenuOpen(!menuOpen)} aria-label={menuOpen ? 'Close add menu' : 'Add a habit or task'} aria-expanded={menuOpen}><Plus size={25}/></button></div><NavButton item={NAV_ITEMS[2]} active={page === NAV_ITEMS[2].id} onClick={() => setPage(NAV_ITEMS[2].id)} compact/><NavButton item={NAV_ITEMS[3]} active={page === NAV_ITEMS[3].id} onClick={() => setPage(NAV_ITEMS[3].id)} compact/></nav>
    <QuickAddMenu open={menuOpen} onClose={closeMenu} onSelect={chooseAdd}/>
    {entryKind === 'habit' && <HabitForm habit={editingHabit} onClose={() => { setEntryKind(null); setEditingHabit(null); }} onSave={saveHabitHandler}/>}
    {entryKind === 'task' && <TaskForm task={editingTask} initialDate={calendarTaskDate} defaultReminder={defaultReminder} onClose={() => { setEntryKind(null); setEditingTask(null); setCalendarTaskDate(''); }} onSave={saveTaskHandler}/>}
    {showSettings && <SettingsModal defaultReminder={defaultReminder} profileName={profileName} onSave={saveDefaultReminder} onSaveName={saveProfileName} onClose={() => setShowSettings(false)}/>}
    {showBulkTasks && <BulkTaskForm defaultReminder={defaultReminder} onClose={() => setShowBulkTasks(false)} onSaveMany={saveManyTasksHandler}/>}
    {showBulkHabits && <BulkHabitForm onClose={() => setShowBulkHabits(false)} onSaveMany={saveManyHabitsHandler}/> }
    {showHelp && <div className="modal-scrim" role="presentation" onMouseDown={e => e.target === e.currentTarget && setShowHelp(false)}><section className="help-modal" role="dialog" aria-modal="true" aria-labelledby="help-title"><div className="modal-heading"><div><span className="tiny-label">DAYMARK · LOCAL-FIRST</span><h2 id="help-title">Your data stays on this device</h2></div><button className="icon-button" onClick={() => setShowHelp(false)} aria-label="Close"><X size={19}/></button></div><div className="help-content"><div className="help-icon"><Settings2 size={21}/></div><p>Habits, tasks, and their history are stored in this browser using IndexedDB. They do not automatically sync to another device, and browser data can be cleared by browser settings.</p><p>Download a backup regularly and keep the JSON file somewhere safe. Restoring a backup replaces the current Daymark data on this device.</p><div className="backup-actions"><button className="primary-button full-button" onClick={exportBackup} disabled={backupBusy}><Download size={16}/>{backupBusy ? 'Working…' : 'Download backup'}</button><label className={`secondary-button full-button backup-import-button ${backupBusy ? 'is-disabled' : ''}`}><Upload size={16}/> Restore from backup<input type="file" accept="application/json,.json" onChange={importBackup} disabled={backupBusy} /></label></div></div><button className="secondary-button full-button" onClick={() => setShowHelp(false)}>Close <Check size={16}/></button></section></div>}
    {toast && <div className="toast-message" role="status"><CheckCircle2 size={17}/>{toast}</div>}
  </div>;
}
export default App;
